//! `concat_ws` with ARRAY arguments against Spark (P3-1): each case of
//! `tests/fixtures/spark-4.2.0/concat-ws-array-goldens.json` (generated by
//! `tests/scripts/gen_concat_ws_array_goldens.py` from a real Spark run, ANSI on and off) runs through a session and
//! must give Spark's type, nullability and bytes, or Spark's error class, SQLSTATE, message parameters and the
//! message's text (which pins the second parameter's `requiredType`, `("ARRAY<STRING>" or "STRING")`).
//! Spark 4.0.0, 4.1.0, 4.2.0 and 4.3.0 gave identical results for every case.
#![cfg(test)]

use std::fmt::Write as _;
use std::path::Path;

use arrow_array::cast::AsArray;
use arrow_array::{Array, ArrayRef};
use arrow_schema::DataType;
use futures::executor::block_on;
use krishiv_session::Session;
use serde_json::Value;

/// Cases where the engine differs from Spark today, each with the reason. A listed case must still differ,
/// so closing one forces the list to shrink.
/// Each entry: id, text the mismatch report must contain, reason.
const PENDING: [(&str, &str, &str); 2] = [
    (
        "array_binary_non_utf8.ansi",
        "INVALID_UTF8_STRING",
        "Spark keeps the bytes of a non-UTF-8 BINARY cast to STRING (hex FF); this engine's strings are UTF-8 and ANSI raises INVALID_UTF8_STRING",
    ),
    (
        "array_binary_non_utf8.legacy",
        "EFBFBD",
        "Spark keeps the bytes (hex FF); this engine's strings are UTF-8 and the cast replaces them with U+FFFD",
    ),
];

fn fixture() -> Value {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/spark-4.2.0/concat-ws-array-goldens.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn hex(bytes: &[u8]) -> String {
    use std::fmt::Write as _;
    bytes.iter().fold(String::new(), |mut s, b| {
        let _ = write!(s, "{b:02X}");
        s
    })
}

/// A result value as the hex of its bytes, or `Null`.
fn hex_at(a: &ArrayRef, i: usize) -> Value {
    if a.is_null(i) || a.data_type() == &DataType::Null {
        return Value::Null;
    }
    let bytes: Vec<u8> = match a.data_type() {
        DataType::Utf8View => a.as_string_view().value(i).as_bytes().to_vec(),
        DataType::LargeUtf8 => a.as_string::<i64>().value(i).as_bytes().to_vec(),
        DataType::Utf8 => a.as_string::<i32>().value(i).as_bytes().to_vec(),
        DataType::Binary => a.as_binary::<i32>().value(i).to_vec(),
        t => panic!("result type {t}"),
    };
    Value::String(hex(&bytes))
}

/// The mismatches of one case, as text (empty when it matches).
fn check(s: &Session, case: &Value) -> String {
    let mut out = String::new();
    let id = case["id"].as_str().unwrap();
    let conf = s.conf();
    let ansi = if case["ansi"].as_bool().unwrap() {
        "true"
    } else {
        "false"
    };
    conf.set("spark.sql.ansi.enabled", ansi).unwrap();
    let result = block_on(async {
        let df = s.sql(case["sql"].as_str().unwrap()).await?;
        let schema = df.schema().await?;
        let batches = df.collect().await?;
        Ok::<_, krishiv_common::error::KrishivError>((schema, batches))
    });
    conf.unset("spark.sql.ansi.enabled").unwrap();
    match (case["ok"].as_bool().unwrap(), result) {
        (true, Ok((schema, batches))) => {
            let f = &schema.fields()[0];
            let ty = krishiv_types::DataType::from_arrow(f.data_type())
                .map(|t| t.simple_string())
                .unwrap_or_default();
            if schema.fields().len() != 1
                || ty != case["type"].as_str().unwrap()
                || f.is_nullable() != case["nullable"].as_bool().unwrap()
            {
                let _ = writeln!(
                    out,
                    "{id}: column {}:{ty}:{} vs Spark {}:{}",
                    f.name(),
                    f.is_nullable(),
                    case["type"],
                    case["nullable"]
                );
            }
            let mut got: Vec<Vec<Value>> = Vec::new();
            for b in &batches {
                for i in 0..b.num_rows() {
                    got.push(vec![hex_at(b.column(0), i)]);
                }
            }
            let want: Vec<Vec<Value>> = case["rows_hex"]
                .as_array()
                .unwrap()
                .iter()
                .map(|r| r.as_array().unwrap().clone())
                .collect();
            if got != want {
                let _ = writeln!(out, "{id}: rows\n  got  {got:?}\n  want {want:?}");
            }
        }
        (false, Err(e)) => {
            let class = e.error_class().name();
            let params: serde_json::Map<String, Value> = e
                .message_parameters()
                .iter()
                .map(|(k, v)| ((*k).to_owned(), Value::String(v.clone())))
                .collect();
            let want_class = case["error_class"].as_str().unwrap();
            let want_params = case["message_parameters"].as_object().unwrap();
            let want_state = case["sql_state"].as_str();
            if class != want_class || &params != want_params || e.sql_state() != want_state {
                let _ = writeln!(
                    out,
                    "{id}: error {class} {:?} {params:?}\n  Spark {want_class} {want_state:?} {want_params:?}",
                    e.sql_state()
                );
            }
            // The text between "due to data type mismatch: " and " SQLSTATE" is the sentence a user reads.
            let spark = case["message"].as_str().unwrap();
            let sentence = spark
                .split_once("due to data type mismatch: ")
                .and_then(|(_, rest)| rest.split_once(" SQLSTATE"))
                .map(|(s, _)| s);
            if let Some(sentence) = sentence
                && !e.message().contains(sentence)
            {
                let _ = writeln!(
                    out,
                    "{id}: message {:?}\n  Spark sentence {sentence:?}",
                    e.message()
                );
            }
        }
        (true, Err(e)) => {
            let _ = writeln!(out, "{id}: failed: {e}");
        }
        (false, Ok(_)) => {
            let _ = writeln!(out, "{id}: ran; Spark raised {}", case["error_class"]);
        }
    }
    out
}

#[test]
fn concat_ws_array_matches_spark() {
    let g = fixture();
    let s = Session::new().unwrap();
    let cases = g["cases"].as_array().unwrap();
    let mut report = String::new();
    let mut failing: Vec<&str> = Vec::new();
    let mut pinned: Vec<(&str, String)> = Vec::new();
    for case in cases {
        let r = check(&s, case);
        if !r.is_empty() {
            failing.push(case["id"].as_str().unwrap());
            pinned.push((case["id"].as_str().unwrap(), r.clone()));
        }
        if !PENDING
            .iter()
            .any(|(id, _, _)| *id == case["id"].as_str().unwrap())
        {
            report.push_str(&r);
        }
    }
    for (id, how, reason) in PENDING {
        assert!(
            failing.contains(&id),
            "pending case {id} ({reason}) now passes: remove it"
        );
        // Pin how it differs, so a different wrong answer is noticed too.
        let got = &pinned.iter().find(|(i, _)| *i == id).unwrap().1;
        assert!(
            got.contains(how),
            "pending case {id} differs differently: {got}"
        );
    }
    // Both modes of the cases that pin the behaviour.
    let ids: Vec<&str> = cases.iter().map(|c| c["id"].as_str().unwrap()).collect();
    for id in [
        "mixed_all",
        "null_separator",
        "array_binary_non_utf8",
        "refuse_array_of_map",
        "refuse_map_argument",
    ] {
        for mode in ["ansi", "legacy"] {
            let want = format!("{id}.{mode}");
            assert!(
                ids.contains(&want.as_str()),
                "case {want} is missing from the fixture"
            );
        }
    }
    assert!(report.is_empty(), "mismatches against Spark:\n{report}");
}
